"""Symbolic type/aggregate visitors and the strict inverse reader.

``MainBuilder`` fixes the numbering convention of the symbolic harness: inputs
in parameter order, then a non-void result, starting at ``x0``; every visited
bool, char, int, enum, string buffer, array or struct reserves one increasing
``xN``.  A scalar owns one object; a composite itself owns no object and its
children reserve identifiers recursively; ``String(N)`` owns ``N`` character
objects after its buffer identifier; an alias reserves no identifier and adds
no path component; even a zero length composite reserves its own identifier;
void reserves nothing.

``HarnessLayout`` is that convention made reusable: it produces the ordered
scalar slots (``[object_name, path, byte_width]``), the reserved identifier
inventory, and cursor based value templates.  ``ResultReader`` is the strict
inverse: a missing, unexpected, mis-sized or out-of-range object is an error
and is never repaired by skipping to a nearby ``xN``.
"""

from typing import Dict, List

from eywa.ast import (Alias, Array, Bool, Char, Enum, Int, NodeVisitor, String,
                      Struct, Type, Void, int_width)

__all__ = ['TypeBuilder', 'DefinitionBuilder', 'TypeCollector', 'MainBuilder',
           'ResultReader', 'HarnessLayout', 'InventoryError', 'leaf_value']


class InventoryError(Exception):
    """A symbolic object inventory or leaf value that cannot be recovered."""


class TypeBuilder(NodeVisitor):
    """
    A class that converts an Eywa type to a C type.
    """

    @staticmethod
    def build(type: Type):
        """
        Convert an Eywa type to a C type as a string.
        """
        return TypeBuilder().visit(type)

    def visit_Void(self, node):
        return "void", ""

    def visit_Bool(self, node):
        return "bool", ""

    def visit_Char(self, node):
        return "char", ""

    def visit_Int(self, node):
        if node.size == 64:
            return "uint64_t", ""
        if node.size == 32:
            return "uint32_t", ""
        if node.size == 16:
            return "uint16_t", ""
        if node.size == 8:
            return "uint8_t", ""
        return "int", f": {node.size}"

    def visit_String(self, node):
        return "char*", ""

    def visit_Enum(self, node):
        return node.name, ""

    def visit_Array(self, node):
        (left, right) = self.visit(node.element_type)
        return left, f"{right}[{node.maxsize}]"

    def visit_Struct(self, node):
        return node.name, ""

    def visit_Alias(self, node):
        return node.name, ""


class DefinitionBuilder(NodeVisitor):
    """
    A class that creates a C type definition (if needed) for
    a given Eywa type. This includes enums, structs, and aliases.
    """

    @staticmethod
    def build(type: Type):
        """
        Build a C type definition for an Eywa type if necessary.
        """
        return DefinitionBuilder().visit(type)

    def visit_Void(self, node):
        return None

    def visit_Bool(self, node):
        return None

    def visit_Char(self, node):
        return None

    def visit_Int(self, node):
        return None

    def visit_String(self, node):
        return None

    def visit_Enum(self, node):
        return f'typedef enum {{ {", ".join(node.values)} }} {node.name};\n'

    def visit_Array(self, node):
        return None

    def visit_Struct(self, node):
        field_strs = []
        for (field_name, field) in node.fields.items():
            (left, right) = TypeBuilder.build(field)
            field_strs.append(f"{left} {field_name}{right};")
        fields = " ".join(field_strs)
        return f'typedef struct {{ {fields} }} {node.name};\n'

    def visit_Alias(self, node):
        (left, right) = TypeBuilder.build(node.type)
        description = "" if node.description is None else '\n'.join(
            [f'// {line}' for line in node.description.splitlines()]) + '\n'
        return f'{description}typedef {left} {node.name}{right};\n'


class TypeCollector(NodeVisitor):
    """
    A class to recursively extract all of the Ewya sub-types in a type.
    """

    @staticmethod
    def collect(type: Type, results: List[Type]):
        """
        Collect all the Eywa types in a given type.
        """
        TypeCollector(results).visit(type)

    def __init__(self, result):
        self.result = result

    def visit_Void(self, node):
        self.result.append(node)

    def visit_Bool(self, node):
        self.result.append(node)

    def visit_Char(self, node):
        self.result.append(node)

    def visit_Int(self, node):
        self.result.append(node)

    def visit_String(self, node):
        self.result.append(node)

    def visit_Enum(self, node):
        self.result.append(node)

    def visit_Array(self, node):
        self.visit(node.element_type)
        self.result.append(node)

    def visit_Struct(self, node):
        for (_, field) in node.fields.items():
            self.visit(field)
        self.result.append(node)

    def visit_Alias(self, node):
        self.visit(node.type)
        self.result.append(node)


class MainBuilder(NodeVisitor):
    """
    A class to build the KLEE main function that creates the symbolic
    inputs and runs the implementation given by the model.

    The numbering below is the authoritative harness convention; every other
    component (slots, inventory checks, inverse reading) is derived from
    :class:`HarnessLayout`, which implements exactly this walk.
    """

    def __init__(self, result):
        self.result = result
        self.number = 0

    def _next(self):
        n = self.number
        self.number = self.number + 1
        return f'x{n}'

    def _is_array(self, node):
        while isinstance(node, Alias):
            node = node.type
        return isinstance(node, Array)

    def visit_Void(self, node):
        raise Exception('Cannot create an instance of the Void type')

    def visit_Bool(self, node):
        var = self._next()
        self.result.append(f'bool {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_Char(self, node):
        var = self._next()
        self.result.append(f'char {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_Int(self, node):
        var = self._next()
        self.result.append(f'{TypeBuilder.build(node)[0]} {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        return var

    def visit_String(self, node):
        var1 = self._next()
        self.result.append(f'char {var1}[{node.maxsize + 1}];')
        for i in range(0, node.maxsize):
            cvar = self.visit(node.char_type)
            self.result.append(f'{var1}[{i}] = {cvar};')
        self.result.append(f"{var1}[{node.maxsize}] = '\\0';")
        return var1

    def visit_Enum(self, node):
        var = self._next()
        self.result.append(f'{node.name} {var};')
        self.result.append(
            f'klee_make_symbolic(&{var}, sizeof({var}), "{var}");')
        self.result.append(f'klee_assume({var} >= 0);')
        self.result.append(f'klee_assume({var} < {len(node.values)});')
        return var

    def visit_Array(self, node):
        var = self._next()
        (left, right) = TypeBuilder.build(node.element_type)
        self.result.append(f'{left} {var}{right}[{node.maxsize}];')
        for i in range(0, node.maxsize):
            evar = self.visit(node.element_type)
            self.result.append(f'{var}[{i}] = {evar};')
        return var

    def visit_Struct(self, node):
        var = self._next()
        self.result.append(f'{node.name} {var};')
        for (field_name, field) in node.fields.items():
            field_var = self.visit(field)
            if self._is_array(field):
                self.result.append(
                    f'memcpy({var}.{field_name}, {field_var}, sizeof({field_var}));')
            else:
                self.result.append(f'{var}.{field_name} = {field_var};')
        return var

    def visit_Alias(self, node):
        # An alias is transparent: it reserves no identifier of its own.
        return self.visit(node.type)


def leaf_value(kind: str, aux, raw: int):
    """Validate and convert one little-endian symbolic leaf."""
    if kind == 'b':
        if raw > 1:
            raise InventoryError('boolean object must be 0 or 1')
        return raw != 0
    if kind == 'c':
        if raw > 255:
            raise InventoryError('character object out of range')
        return chr(raw)
    if kind == 'i':
        if raw >> aux:
            raise InventoryError('integer object has padding bits set')
        return raw
    if kind == 'e':
        if raw >= len(aux):
            raise InventoryError('enumeration index out of range')
        return aux[raw]
    raise InventoryError('unknown leaf kind')


class _Cursor(object):
    __slots__ = ('nums', 'pos')

    def __init__(self, nums):
        self.nums = nums
        self.pos = 0

    def take(self, template):
        kind = template[0]
        if kind == 'i':
            value = self.nums[self.pos]
            self.pos += 1
            return value
        if kind == 'b':
            value = self.nums[self.pos]
            self.pos += 1
            return value != 0
        if kind == 'c':
            value = chr(self.nums[self.pos])
            self.pos += 1
            return value
        if kind == 'e':
            value = template[1][self.nums[self.pos]]
            self.pos += 1
            return value
        if kind == 's':
            start = self.pos
            size = template[1]
            end = start + size
            self.pos = end
            if size == 0:
                return ""
            window = self.nums[start:end]
            try:
                stop = window.index(0)
            except ValueError:
                stop = size
            return bytes(window[:stop]).decode('latin-1')
        if kind == 'a':
            count = template[1]
            if count == 0:
                return []
            sub = template[2]
            take = self.take
            return [take(sub) for _ in range(count)]
        if kind == 't':
            return {name: self.take(sub) for name, sub in template[1]}
        return None


def make_template(node_type: Type):
    """Build the cursor template that recovers values for a type."""
    inner = Type.inner(node_type)
    if isinstance(inner, Void):
        return ('v',)
    if isinstance(inner, Bool):
        return ('b',)
    if isinstance(inner, Char):
        return ('c',)
    if isinstance(inner, Int):
        return ('i',)
    if isinstance(inner, Enum):
        return ('e', inner.values)
    if isinstance(inner, String):
        return ('s', inner.maxsize)
    if isinstance(inner, Array):
        count = inner.maxsize
        if count == 0:
            return ('a', 0, None)
        return ('a', count, make_template(inner.element_type))
    if isinstance(inner, Struct):
        return ('t', tuple((name, make_template(field))
                           for name, field in inner.fields.items()))
    raise Exception(f'unknown type {inner!r}')


class HarnessLayout(object):
    """The compiled symbolic harness layout of one entry.

    Attributes:
        slots: ordered ``[object_name, path, byte_width]`` scalar objects.
        flat: matching ordered leaf descriptors ``(name, width, kind, aux)``.
        names: every reserved identifier, in reservation order.
        widths: identifier to byte width, including the composite identifiers.
        variables: total number of reserved identifiers, flag included.
        flag: the ``bad_input`` identifier name, or ``None``.
        inputs: ordered ``(parameter_name, template)`` pairs.
        result_name / result_template: the by-value result recovery.
    """

    def __init__(self, params, result=None, needs_flag=False):
        self.number = 0
        self.slots = []
        self.flat = []
        self.names = []
        self.widths = {}
        self.inputs = []
        self.result_name = None
        self.result_template = ('v',)
        self.flag = None
        self._composite_names = []
        for (name, node_type) in params:
            self.inputs.append((name, make_template(node_type)))
            self._walk(node_type, [name])
        if result is not None:
            result_name, result_type = result
            if not isinstance(Type.inner(result_type), Void):
                self.result_name = result_name
                self.result_template = make_template(result_type)
                self._walk(result_type, [result_name])
        if needs_flag:
            self.flag = self._reserve(1)
        self.variables = self.number
        self.expected = frozenset(self.widths)
        self._input_count = sum(1 for _ in self.inputs)

    # -- numbering ------------------------------------------------------
    def _reserve(self, width=None):
        name = f'x{self.number}'
        self.number += 1
        self.names.append(name)
        if width is not None:
            self.widths[name] = width
        else:
            self._composite_names.append(name)
        return name

    def _scalar(self, name, path, width, kind, aux):
        self.widths[name] = width
        self.slots.append([name, path, width])
        self.flat.append((name, width, kind, aux))

    def _walk(self, node_type, path):
        inner = node_type
        while isinstance(inner, Alias):
            inner = inner.type
        if isinstance(inner, Void):
            return
        if isinstance(inner, Bool):
            self._scalar(self._reserve(), path, 1, 'b', None)
            return
        if isinstance(inner, Char):
            self._scalar(self._reserve(), path, 1, 'c', None)
            return
        if isinstance(inner, Int):
            width = int_width(inner.size)
            self._scalar(self._reserve(), path, width, 'i', inner.size)
            return
        if isinstance(inner, Enum):
            self._scalar(self._reserve(), path, 4, 'e', inner.values)
            return
        if isinstance(inner, String):
            self._reserve()  # the character buffer itself owns no object
            size = inner.maxsize
            for index in range(size):
                self._scalar(self._reserve(), path + [index], 1, 'c', None)
            return
        if isinstance(inner, Array):
            self._reserve()  # the array itself owns no object
            element = inner.element_type
            for index in range(inner.maxsize):
                self._walk(element, path + [index])
            return
        if isinstance(inner, Struct):
            self._reserve()  # the struct itself owns no object
            for field_name, field_type in inner.fields.items():
                self._walk(field_type, path + [field_name])
            return
        raise Exception(f'unknown type {inner!r}')

    # -- inverse reading ------------------------------------------------
    def decode(self, objects: Dict[str, bytes]):
        """Recover leaf integers from named blobs, strictly.

        Returns ``(leaves, flag)`` where ``leaves`` is a list of raw unsigned
        integers in harness order and ``flag`` is the recovered ``bad_input``
        boolean (or ``None`` when the entry has no pipes).
        """
        if set(objects) != set(self.widths):
            raise InventoryError('object inventory does not match the harness')
        flat = self.flat
        leaves = [0] * len(flat)
        index = 0
        for (name, width, kind, aux) in flat:
            data = objects[name]
            if len(data) != width:
                raise InventoryError(f'object {name} has width {len(data)}, expected {width}')
            raw = int.from_bytes(data, 'little')
            if kind == 'b':
                if raw > 1:
                    raise InventoryError(f'object {name} is not a boolean')
            elif kind == 'i':
                if raw >> aux:
                    raise InventoryError(f'object {name} has padding bits set')
            elif kind == 'e':
                if raw >= len(aux):
                    raise InventoryError(f'object {name} is out of enumeration range')
            leaves[index] = raw
            index += 1
        flag = None
        if self.flag is not None:
            data = objects[self.flag]
            if len(data) != 1:
                raise InventoryError('bad_input flag must be one byte wide')
            flag = int.from_bytes(data, 'little')
            if flag > 1:
                raise InventoryError('bad_input flag must be 0 or 1')
        return leaves, flag

    def values(self, leaves):
        """Recover the entry inputs and the by-value result from leaves."""
        cursor = _Cursor(leaves)
        inputs = {name: cursor.take(template) for name, template in self.inputs}
        result = cursor.take(self.result_template) if self.result_name else None
        return inputs, result


class ResultReader(NodeVisitor):
    """
    Class to read the results of a run and convert them to Python values.

    The reader is the exact inverse of :class:`MainBuilder`: identifiers are
    consumed in harness order, every expected object must be present with its
    declared width, and no object is ever skipped.
    """

    def __init__(self, assignment: Dict[str, int]):
        self.number = 0
        self.assignment = dict(assignment)

    def _next(self):
        n = self.number
        self.number = self.number + 1
        return f'x{n}'

    def _lookup(self, width):
        name = self._next()
        if name not in self.assignment:
            raise InventoryError(f'missing symbolic object {name}')
        value = self.assignment[name]
        if width is not None and value >= (1 << (8 * width)):
            raise InventoryError(f'symbolic object {name} exceeds {width} bytes')
        return value

    def visit_Void(self, node):
        raise Exception('Cannot create an instance of the Void type')

    def visit_Bool(self, node):
        return leaf_value('b', None, self._lookup(1))

    def visit_Char(self, node):
        return leaf_value('c', None, self._lookup(1))

    def visit_Int(self, node):
        return leaf_value('i', node.size, self._lookup(int_width(node.size)))

    def visit_String(self, node):
        self._next()  # the character buffer owns no object
        chars = []
        for _ in range(0, node.maxsize):
            chars.append(self.visit(node.char_type))
        text = ""
        for char in chars:
            if char == '\0':
                break
            text += char
        return text

    def visit_Enum(self, node):
        return leaf_value('e', node.values, self._lookup(4))

    def visit_Array(self, node):
        self._next()  # the array itself owns no object
        result = []
        for _ in range(0, node.maxsize):
            result.append(self.visit(node.element_type))
        return result

    def visit_Struct(self, node):
        self._next()  # the struct itself owns no object
        result = {}
        for (field_name, field) in node.fields.items():
            result[field_name] = self.visit(field)
        return result

    def visit_Alias(self, node):
        return self.visit(node.type)
